-- The CHAM-GROOVE code key (Code keys -> Parting -> CHAM-GROOVE), from the
-- ISCAR e-catalog's CHAM-GROOVE families (GIQR/L, GFQR inserts, MGCH bars);
-- kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.chamgroove', $ck${"title": "CHAM-GROOVE code key – inserts and bars", "subtitle": "Precision ground single-ended inserts (GIQR/L, GFQR) for internal and face grooving, turning and profiling in small bores, and MGCH solid carbide bars", "example": "GIQR 8-1.50-0.05", "decoder": "cham-groove", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GIQ", "rows": [{"code": "GIQ", "meaning": "Precision ground single-ended inserts for internal grooving, turning and profiling"}, {"code": "GFQ", "meaning": "Face grooving inserts (GFQR, on MGCH 09C face tools)"}]}, {"key": "i-hand", "title": "Insert – hand", "sample": "R", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-size", "title": "Insert – size", "sample": "8", "rows": [{"code": "8", "meaning": "Size 8 – minimum bore diameter 8 mm (MGCH 06 / 08 bars)"}, {"code": "11", "meaning": "Size 11 – minimum bore diameter 11 mm"}, {"code": "12", "meaning": "GFQR 12 – minimum face groove diameter 12 mm"}]}, {"key": "i-deep", "title": "Insert – deep grooving", "rows": [{"code": "15", "meaning": "Deep grooving and turning version, minimum bore diameter 15 mm (e.g. GIQR 11-15-...)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "1.50", "rows": [{"code": "#.##", "meaning": "Cutting width in mm (e.g. 1.50)"}]}, {"key": "i-type", "title": "Insert – profiling type", "rows": [{"code": "A18", "meaning": "Internal boring and profiling, 18° (e.g. GIQR 8-A18-0.15)"}, {"code": "B18", "meaning": "Internal back boring and profiling, 18° (e.g. GIQR 8-B18-0.15)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "0.05", "rows": [{"code": "#.##", "meaning": "Corner radius in mm (0.00 = sharp, for grooving only)"}, {"code": "R###", "meaning": "Full radius x 100 (e.g. R100 = 1.00 mm) for grooving and profiling"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "MGCH", "meaning": "Solid carbide bars for internal grooving, turning and threading (and MGCH 09C face tools for GFQR)"}]}, {"key": "t-height", "title": "Tool – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (06, 08, 09)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "C", "meaning": "With coolant supply"}]}, {"key": "t-length", "title": "Tool – length", "rows": [{"code": "L###", "meaning": "Bar length in mm (e.g. L100, L125)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
